/* Sachgebiet 1: Recht der öffentlichen Sicherheit und Ordnung einschließlich Gewerberecht.
   Eigene prüfungsnahe Übungsfragen – keine Original-IHK-Fragen.
   Format: erste Option(en) richtig, Anzeige mischt. Neue Fragen nur am Ende anhängen (IDs!). */
SK.fragen("oso", [
  { u: "gg", d: 1, q: "Welches Rechtsgut stellt Art. 1 des Grundgesetzes an die Spitze der Grundrechte?", o: ["Die Würde des Menschen", ["Das Eigentum", "Das Eigentum wird in Art. 14 GG gewährleistet."], ["Die Berufsfreiheit", "Die Berufsfreiheit steht in Art. 12 GG."], ["Die Unverletzlichkeit der Wohnung", "Diese regelt Art. 13 GG."]], e: "Art. 1 Abs. 1 GG: Die Würde des Menschen ist unantastbar. Sie zu achten und zu schützen ist Verpflichtung aller staatlichen Gewalt.", r: "Art. 1 GG" },
  { u: "gg", d: 2, q: "Wen binden die Grundrechte nach Art. 1 Abs. 3 GG unmittelbar?", o: ["Gesetzgebung, vollziehende Gewalt und Rechtsprechung", ["Alle Unternehmen mit mehr als 20 Beschäftigten", "Private Unternehmen sind nicht unmittelbar Grundrechtsverpflichtete."], ["Nur die Polizei", "Gebunden ist die gesamte Staatsgewalt, nicht nur die Polizei."], ["Jede Privatperson im Verhältnis zu anderen", "Zwischen Privaten wirken Grundrechte nur mittelbar über die Gesetze."]], e: "Die Grundrechte binden die drei Staatsgewalten als unmittelbar geltendes Recht. Auf das Verhältnis zwischen Privaten strahlen sie über die Auslegung der Gesetze aus.", r: "Art. 1 Abs. 3 GG" },
  { u: "gg", d: 1, q: "Welche Rechte schützt Art. 2 Abs. 2 GG?", o: ["Leben, körperliche Unversehrtheit und Freiheit der Person", ["Eigentum und Erbrecht", "Das ist Art. 14 GG."], ["Brief-, Post- und Fernmeldegeheimnis", "Das ist Art. 10 GG."], ["Meinungs- und Pressefreiheit", "Das ist Art. 5 GG."]], e: "Art. 2 Abs. 2 GG schützt Leben, körperliche Unversehrtheit und die Freiheit der Person. Eingriffe sind nur aufgrund eines Gesetzes zulässig.", r: "Art. 2 Abs. 2 GG" },
  { u: "gg", d: 2, q: "Eine Wachperson hält einen Ladendieb bis zum Eintreffen der Polizei fest. In welches Grundrecht greift das Festhalten vor allem ein?", f: 1, o: ["Freiheit der Person (Art. 2 Abs. 2 GG)", ["Unverletzlichkeit der Wohnung (Art. 13 GG)", "Die Wohnung des Betroffenen ist nicht berührt."], ["Berufsfreiheit (Art. 12 GG)", "Die Berufsausübung des Betroffenen ist nicht betroffen."], ["Versammlungsfreiheit (Art. 8 GG)", "Es liegt keine Versammlung vor."]], e: "Festhalten beschränkt die körperliche Bewegungsfreiheit. Deshalb braucht es eine gesetzliche Rechtfertigung, hier § 127 Abs. 1 StPO.", r: "Art. 2 Abs. 2 GG; § 127 Abs. 1 StPO" },
  { u: "gg", t: "mc", d: 2, q: "Welche zwei Aussagen zu Art. 3 GG treffen zu?", o: ["Alle Menschen sind vor dem Gesetz gleich.", "Niemand darf wegen seiner Herkunft, seines Glaubens oder seines Geschlechts benachteiligt oder bevorzugt werden.", ["Art. 3 GG garantiert jedem denselben Lohn.", "Art. 3 GG ist ein Gleichheitssatz, kein Anspruch auf gleiche Bezahlung in jedem Fall."], ["Art. 3 GG gilt nur für deutsche Staatsangehörige.", "Art. 3 GG ist ein Menschenrecht („alle Menschen“)."]], e: "Art. 3 GG enthält den allgemeinen Gleichheitssatz und besondere Diskriminierungsverbote. Für den Wachdienst heißt das: Kontrollen dürfen nicht an Herkunft oder Aussehen anknüpfen.", r: "Art. 3 GG" },
  { u: "gg", t: "tf", d: 2, a: false, q: "Eine Wachperson ist bei ihrer Tätigkeit genauso unmittelbar an die Grundrechte gebunden wie eine Polizeibeamtin.", e: "Unmittelbar gebunden ist nur die Staatsgewalt. Private müssen aber die Gesetze beachten, in denen sich die Grundrechte niederschlagen (z. B. StGB, BGB, AGG, DS-GVO).", r: "Art. 1 Abs. 3 GG" },
  { u: "gg", d: 2, q: "Wer entscheidet nach Art. 104 GG über die Zulässigkeit und Fortdauer einer Freiheitsentziehung?", o: ["Nur der Richter", ["Die Polizei abschließend", "Die Polizei darf nur vorläufig festhalten und muss unverzüglich eine richterliche Entscheidung herbeiführen."], ["Der Inhaber des Hausrechts", "Private können keine Freiheitsentziehung anordnen."], ["Das Ordnungsamt", "Auch Ordnungsbehörden brauchen die richterliche Entscheidung."]], e: "Art. 104 Abs. 2 GG: Über Zulässigkeit und Fortdauer einer Freiheitsentziehung hat nur der Richter zu entscheiden. Deshalb ist eine von Privaten festgehaltene Person unverzüglich der Polizei zu übergeben.", r: "Art. 104 GG" },
  { u: "gg", t: "tf", d: 2, a: true, q: "Auch wenn ein Grundrecht durch Gesetz oder aufgrund eines Gesetzes eingeschränkt werden kann, darf es in keinem Fall in seinem Wesensgehalt angetastet werden.", e: "Art. 19 Abs. 2 GG: In keinem Falle darf ein Grundrecht in seinem Wesensgehalt angetastet werden. Nach Abs. 1 muss das einschränkende Gesetz allgemein gelten und das Grundrecht nennen.", r: "Art. 19 Abs. 1 und 2 GG" },
  { u: "gg", d: 2, q: "Die Erlaubnispflicht für das Bewachungsgewerbe schränkt ein Grundrecht ein. Welches?", o: ["Berufsfreiheit (Art. 12 GG)", ["Meinungsfreiheit (Art. 5 GG)", "Die Erlaubnispflicht betrifft keine Meinungsäußerung."], ["Eigentum (Art. 14 GG)", "Betroffen ist die Berufsausübung, nicht das Eigentum."], ["Freizügigkeit (Art. 11 GG)", "Die Wahl des Aufenthaltsorts ist nicht berührt."]], e: "Art. 12 GG gewährleistet die freie Berufswahl. Die Berufsausübung kann durch Gesetz geregelt werden – hier durch § 34a GewO.", r: "Art. 12 GG; § 34a GewO" },
  { u: "gg", t: "fa", d: 3, q: "Erkläre, warum eine Wachperson die Grundrechte beachten muss, obwohl diese unmittelbar nur den Staat binden.", m: "Die Grundrechte sind Abwehrrechte gegen den Staat. Sie prägen aber als Wertordnung die gesamte Rechtsordnung. Ihr Schutz wird zwischen Privaten durch einfache Gesetze verwirklicht: Das StGB schützt Leben, Körper, Freiheit, Ehre und Eigentum, das BGB gewährt Schadensersatz, das AGG verbietet Benachteiligung, die DS-GVO schützt die informationelle Selbstbestimmung. Wer als Wachperson diese Gesetze verletzt, handelt rechtswidrig. Man spricht von mittelbarer Wirkung der Grundrechte.", c: ["Grundrechte = Abwehrrechte gegen den Staat", "mittelbare Wirkung über einfache Gesetze", "Beispiele: StGB, BGB, AGG, DS-GVO"] },

  { u: "staat", d: 1, q: "Was bedeutet Föderalismus in der Bundesrepublik Deutschland?", o: ["Die staatlichen Aufgaben sind zwischen Bund und Ländern aufgeteilt.", ["Alle Gesetze werden ausschließlich vom Bund erlassen.", "Auch die Länder haben eigene Gesetzgebungszuständigkeiten."], ["Die Gemeinden sind dem Bund direkt unterstellt.", "Gemeinden gehören zu den Ländern."], ["Die Polizei ist bundesweit einheitlich organisiert.", "Die Polizei ist grundsätzlich Sache der Länder."]], e: "Deutschland ist ein Bundesstaat (Art. 20 GG). Bund und Länder haben jeweils eigene Zuständigkeiten.", r: "Art. 20, 30, 70 GG" },
  { u: "staat", d: 2, q: "Wer regelt grundsätzlich das Polizei- und Ordnungsrecht?", o: ["Die Bundesländer in eigenen Gesetzen", ["Der Bund im Strafgesetzbuch", "Das StGB regelt Straftaten, nicht die Befugnisse der Gefahrenabwehr."], ["Die Industrie- und Handelskammern", "Die IHK ist für Unterrichtung und Sachkundeprüfung zuständig."], ["Die Europäische Union", "Die EU hat hierfür keine allgemeine Zuständigkeit."]], e: "Gefahrenabwehr ist Ländersache. Deshalb gibt es 16 Polizeigesetze mit teils unterschiedlichen Begriffen und Befugnissen. In Nordrhein-Westfalen gelten das PolG NRW und das Ordnungsbehördengesetz (OBG).", r: "Art. 30, 70 GG; in NRW: Polizeigesetz (PolG NRW) und Ordnungsbehördengesetz (OBG)" },
  { u: "staat", d: 1, q: "Zu welcher Staatsgewalt gehört die Polizei?", o: ["Zur vollziehenden Gewalt (Exekutive)", ["Zur gesetzgebenden Gewalt (Legislative)", "Die Legislative sind die Parlamente."], ["Zur rechtsprechenden Gewalt (Judikative)", "Die Judikative sind die Gerichte."], ["Zu keiner – sie ist unabhängig", "Die Polizei ist Teil der Verwaltung und damit der Exekutive."]], e: "Die Polizei führt Gesetze aus und gehört damit zur Exekutive.", r: "Art. 20 Abs. 2 GG" },
  { u: "staat", t: "zu", d: 1, q: "Ordne jeder Staatsgewalt das passende Organ zu.", p: [["Legislative", "Bundestag"], ["Exekutive", "Polizei"], ["Judikative", "Amtsgericht"]], e: "Gewaltenteilung nach Art. 20 Abs. 2 GG: Gesetzgebung, vollziehende Gewalt und Rechtsprechung sind getrennt." },
  { u: "staat", d: 2, q: "Was kennzeichnet das öffentliche Recht?", o: ["Ein Verhältnis der Über- und Unterordnung zwischen Staat und Bürger", ["Die Gleichordnung der Beteiligten", "Gleichordnung kennzeichnet das Privatrecht."], ["Es gilt nur für Beamte", "Öffentliches Recht betrifft alle, die dem Staat gegenüberstehen."], ["Es wird ausschließlich durch Verträge begründet", "Das öffentliche Recht beruht auf Gesetzen und hoheitlichen Anordnungen."]], e: "Im öffentlichen Recht tritt der Staat dem Bürger mit hoheitlicher Gewalt gegenüber. Im Privatrecht begegnen sich die Beteiligten gleichgeordnet.", r: "Rechtssystem; Rahmenplan 1a" },
  { u: "staat", t: "mc", d: 2, q: "Welche zwei Rechtsgebiete gehören zum öffentlichen Recht?", o: ["Strafrecht", "Gewerberecht", ["Kaufrecht des BGB", "Das Kaufrecht ist Privatrecht."], ["Mietrecht", "Das Mietrecht ist Privatrecht."]], e: "Straf-, Gewerbe-, Polizei- und Verfassungsrecht sind öffentliches Recht. Das BGB regelt Privatrecht.", r: "Rechtssystem; Rahmenplan 1a" },
  { u: "staat", d: 2, q: "Welchem Rechtsgebiet ist der Bewachungsvertrag zwischen Auftraggeber und Sicherheitsunternehmen zuzuordnen?", o: ["Dem Privatrecht", ["Dem Polizeirecht", "Das Polizeirecht regelt hoheitliche Gefahrenabwehr."], ["Dem Strafrecht", "Das Strafrecht regelt Straftaten und ihre Folgen."], ["Dem Verfassungsrecht", "Verträge zwischen Privaten sind kein Verfassungsrecht."]], e: "Auftraggeber und Sicherheitsunternehmen stehen sich gleichgeordnet gegenüber. Der Vertrag ist privatrechtlich; aus ihm können nur private Rechte übertragen werden.", r: "BGB; § 34a Abs. 5 GewO" },
  { u: "staat", t: "fa", d: 2, q: "Erkläre den Unterschied zwischen öffentlichem Recht und Privatrecht und nenne je ein Beispiel aus dem Wachdienst.", m: "Öffentliches Recht regelt das Verhältnis zwischen Staat und Bürger; der Staat ist übergeordnet und handelt hoheitlich. Beispiel: Die Behörde erteilt oder versagt die Erlaubnis nach § 34a GewO; die Polizei spricht einen Platzverweis aus. Privatrecht regelt die Beziehungen gleichgeordneter Personen. Beispiel: der Bewachungsvertrag oder das Hausrecht, das der Auftraggeber der Wachperson überträgt.", c: ["Über-/Unterordnung vs. Gleichordnung", "Beispiel öffentlich: § 34a-Erlaubnis, Platzverweis", "Beispiel privat: Bewachungsvertrag, Hausrecht"] },

  { u: "monopol", d: 1, q: "Was bedeutet „Gewaltmonopol des Staates“?", o: ["Nur der Staat darf zur Durchsetzung des Rechts Zwang anwenden.", ["Nur der Staat darf Sicherheitsdienstleistungen anbieten.", "Private Sicherheitsdienste sind zulässig; sie haben nur keine Zwangsbefugnisse."], ["Der Staat darf jede Form von Gewalt ohne Gesetz anwenden.", "Auch der Staat braucht für Eingriffe eine gesetzliche Grundlage."], ["Privatpersonen dürfen sich niemals verteidigen.", "Notrechte wie die Notwehr bleiben als Ausnahme bestehen."]], e: "Das Gewaltmonopol verbietet Selbstjustiz. Private dürfen Gewalt nur in den engen Grenzen der Notrechte anwenden.", r: "Art. 20 GG; § 34a Abs. 5 GewO" },
  { u: "monopol", d: 2, q: "Welche Maßnahme ist ausschließlich der Polizei bzw. den Behörden vorbehalten?", o: ["Die zwangsweise Feststellung der Identität", ["Das Aussprechen eines Hausverbots", "Das Hausverbot ist ein privates Recht des Hausrechtsinhabers."], ["Die Abwehr eines Angriffs in Notwehr", "Notwehr steht jedermann zu."], ["Das Festhalten eines auf frischer Tat betroffenen Täters", "Das erlaubt § 127 Abs. 1 StPO jedermann."]], e: "Die Identitätsfeststellung mit Zwang ist eine hoheitliche Befugnis. Private dürfen nach dem Ausweis fragen, die Vorlage aber nicht erzwingen.", r: "§ 163b StPO; § 12 PolG NRW" },
  { u: "monopol", d: 2, q: "Worin unterscheiden sich Platzverweis und Hausverbot?", o: ["Der Platzverweis ist eine polizeiliche Maßnahme, das Hausverbot ein privates Recht des Hausrechtsinhabers.", ["Beides sind polizeiliche Maßnahmen.", "Das Hausverbot beruht auf dem privaten Hausrecht."], ["Beides darf jede Wachperson im öffentlichen Raum aussprechen.", "Im öffentlichen Raum besteht kein Hausrecht; Platzverweise spricht nur die Polizei bzw. Ordnungsbehörde aus."], ["Der Platzverweis gilt nur in Gebäuden.", "Der Platzverweis betrifft gerade auch öffentliche Orte."]], e: "Nach § 34 Abs. 1 PolG NRW kann die Polizei zur Abwehr einer Gefahr eine Person vorübergehend von einem Ort verweisen. Das Hausverbot folgt aus Eigentum und Besitz und kann der Wachperson übertragen werden.", r: "§ 34 PolG NRW; §§ 903, 1004 BGB" },
  { u: "monopol", t: "mc", d: 2, q: "Welche zwei Maßnahmen sind hoheitlich und Wachpersonen nicht erlaubt?", o: ["Beschlagnahme von Gegenständen", "Platzverweis im öffentlichen Raum", ["Hausverbot im Auftrag des Hausrechtsinhabers", "Das ist ein übertragenes privates Recht."], ["Vorläufige Festnahme nach § 127 Abs. 1 StPO", "Dieses Recht steht jedermann zu."]], e: "Beschlagnahme und Platzverweis setzen gesetzliche Befugnisse voraus, die nur Behörden haben.", r: "§ 34a Abs. 5 GewO; § 94 StPO; §§ 34, 43 PolG NRW" },
  { u: "monopol", t: "tf", d: 1, a: false, q: "Eine Wachperson darf den Personalausweis eines Besuchers verlangen und ihn bei Weigerung zwangsweise abnehmen.", e: "Sie darf nach dem Ausweis fragen und bei Weigerung den Zutritt verweigern. Die Vorlage erzwingen oder den Ausweis einbehalten darf sie nicht.", r: "§ 34a Abs. 5 GewO; § 17 BewachV" },
  { u: "monopol", d: 2, f: 1, q: "Am Ausgang eines Kaufhauses bittet eine Wachperson eine Kundin, ihre Tasche zu öffnen. Ein Tatverdacht besteht nicht. Die Kundin lehnt ab. Was gilt?", o: ["Die Kontrolle ist nur freiwillig möglich; ein Öffnen der Tasche darf nicht erzwungen werden.", ["Die Wachperson darf die Tasche gegen den Willen der Kundin durchsuchen.", "Durchsuchungen gegen den Willen sind hoheitliche Maßnahmen."], ["Die Wachperson darf die Kundin festhalten, bis sie einwilligt.", "Ohne frische Tat fehlt jede Grundlage; das wäre Nötigung oder Freiheitsberaubung."], ["Die Kundin macht sich durch die Weigerung strafbar.", "Die Weigerung ist nicht strafbar."]], e: "Ohne Einwilligung oder gesetzliche Grundlage gibt es keine Taschenkontrolle. Möglich sind Hausrechtsmaßnahmen, etwa ein Hausverbot.", r: "§ 34a Abs. 5 GewO; §§ 239, 240 StGB" },
  { u: "monopol", d: 2, q: "Was besagt das Legalitätsprinzip?", o: ["Staatsanwaltschaft und Polizei müssen bei Verdacht einer Straftat ermitteln.", ["Die Polizei entscheidet nach Ermessen, ob sie eine Straftat verfolgt.", "Ermessen besteht bei der Gefahrenabwehr und bei Ordnungswidrigkeiten, nicht bei Straftaten."], ["Private müssen jede Straftat anzeigen.", "Eine allgemeine Anzeigepflicht für Private gibt es nicht; Ausnahme ist § 138 StGB."], ["Jede Handlung ist erlaubt, solange sie nicht bemerkt wird.", "Das ist kein Rechtsgrundsatz."]], e: "Das Legalitätsprinzip (§§ 152 Abs. 2, 163 StPO) verpflichtet die Strafverfolgungsbehörden zum Einschreiten.", r: "§§ 152, 163 StPO" },
  { u: "monopol", d: 2, q: "Welcher Grundsatz gilt für die Polizei bei der Gefahrenabwehr und bei Ordnungswidrigkeiten?", o: ["Opportunitätsprinzip – Einschreiten nach pflichtgemäßem Ermessen", ["Legalitätsprinzip – Pflicht zum Einschreiten in jedem Fall", "Das gilt bei der Strafverfolgung."], ["Subsidiaritätsprinzip – Vorrang privater Sicherheitsdienste", "Private Dienste haben keinen Vorrang vor der Polizei."], ["Verursacherprinzip – der Störer entscheidet", "Der Störer entscheidet nicht über polizeiliche Maßnahmen."]], e: "§ 3 Abs. 1 PolG NRW: Die Polizei trifft ihre Maßnahmen nach pflichtgemäßem Ermessen. Für Ordnungswidrigkeiten gilt § 47 OWiG.", r: "§ 3 Abs. 1 PolG NRW; § 16 OBG NRW; § 47 OWiG" },
  { u: "monopol", t: "mc", d: 1, q: "Welche zwei Aufgaben hat die Polizei?", o: ["Abwehr von Gefahren für die öffentliche Sicherheit und Ordnung", "Erforschung und Verfolgung von Straftaten", ["Rechtsprechung in Strafsachen", "Recht sprechen die Gerichte."], ["Erteilung der Bewachungserlaubnis", "Dafür ist die Gewerbebehörde zuständig."]], e: "Die Polizei handelt präventiv (Gefahrenabwehr) und repressiv (Strafverfolgung).", r: "§ 1 Abs. 1 PolG NRW; § 163 StPO" },
  { u: "monopol", d: 3, q: "Wann schützt die Polizei private Rechte, etwa eine zivilrechtliche Forderung?", o: ["Nur wenn gerichtlicher Schutz nicht rechtzeitig zu erlangen ist und sonst die Verwirklichung des Rechts vereitelt oder wesentlich erschwert würde", ["Immer, sobald ein Bürger darum bittet", "Der Schutz privater Rechte ist grundsätzlich Sache der Zivilgerichte."], ["Nie – private Rechte sind für die Polizei tabu", "In Eilfällen wird die Polizei subsidiär tätig."], ["Nur gegen Zahlung einer Gebühr im Voraus", "Davon hängt die Zuständigkeit nicht ab."]], e: "§ 1 Abs. 2 PolG NRW: Der Schutz privater Rechte obliegt der Polizei nur, wenn gerichtlicher Schutz nicht rechtzeitig zu erlangen ist und ohne polizeiliche Hilfe die Verwirklichung des Rechts vereitelt oder wesentlich erschwert würde.", r: "§ 1 Abs. 2 PolG NRW" },
  { u: "monopol", t: "tf", d: 2, a: false, q: "Beauftragt eine Stadt ein Sicherheitsunternehmen mit Streifengängen in der Innenstadt, erhalten die Wachpersonen dadurch automatisch polizeiliche Befugnisse.", e: "Ein Vertrag kann keine hoheitlichen Befugnisse übertragen. Dazu wäre eine gesetzliche Grundlage (Beleihung) nötig. Die Wachpersonen handeln mit Jedermannsrechten.", r: "§ 34a Abs. 5 GewO" },
  { u: "monopol", d: 3, q: "Unter welcher Voraussetzung können Private ausnahmsweise hoheitliche Befugnisse ausüben?", o: ["Wenn ihnen diese durch Gesetz oder aufgrund eines Gesetzes übertragen wurden (Beleihung)", ["Wenn der Auftraggeber dies im Bewachungsvertrag festlegt", "Ein privater Vertrag kann keine Hoheitsrechte schaffen."], ["Wenn sie Dienstkleidung tragen", "Kleidung verleiht keine Befugnisse."], ["Wenn sie die Sachkundeprüfung bestanden haben", "Die Sachkunde ist eine gewerberechtliche Qualifikation, keine Befugnisnorm."]], e: "Hoheitliche Befugnisse für Private setzen eine gesetzliche Grundlage voraus, etwa bei Luftsicherheitsassistenten. § 34a Abs. 5 GewO spricht deshalb von „gesetzlich übertragenen Befugnissen“.", r: "§ 34a Abs. 5 GewO" },
  { u: "monopol", d: 2, f: 1, q: "Vor einer Veranstaltungshalle staut sich der Verkehr auf der öffentlichen Straße. Darf die Wachperson dort den Verkehr mit verbindlichen Zeichen regeln?", o: ["Nein, die Verkehrsregelung im öffentlichen Straßenraum ist hoheitlich; sie kann nur auf dem Privatgelände einweisen.", ["Ja, sobald sie eine Warnweste trägt", "Eine Warnweste verleiht keine Befugnisse."], ["Ja, wenn der Veranstalter es anordnet", "Der Veranstalter kann keine Hoheitsrechte übertragen."], ["Ja, aber nur nachts", "Die Tageszeit ändert an der Zuständigkeit nichts."]], e: "Verkehrsregelung im öffentlichen Verkehrsraum ist Aufgabe der Polizei. Auf dem Privatgelände darf im Rahmen des Hausrechts eingewiesen werden.", r: "§ 36 StVO; § 34a Abs. 5 GewO" },
  { u: "monopol", t: "fa", d: 2, q: "Grenze die Aufgaben und Befugnisse der Polizei von denen eines privaten Sicherheitsdienstes ab.", m: "Die Polizei ist Teil der Exekutive. Sie wehrt Gefahren für die öffentliche Sicherheit und Ordnung ab und verfolgt Straftaten. Dafür hat sie gesetzliche Eingriffsbefugnisse, z. B. Identitätsfeststellung, Platzverweis, Durchsuchung, Beschlagnahme, Gewahrsam. Der private Sicherheitsdienst schützt im Auftrag eines Kunden dessen Rechtsgüter. Er hat keine hoheitlichen Befugnisse. Ihm stehen die Jedermannsrechte (Notwehr, Notstand, Selbsthilfe, vorläufige Festnahme) und die vom Auftraggeber übertragenen Rechte wie das Hausrecht zu. Dabei ist der Grundsatz der Erforderlichkeit zu beachten (§ 34a Abs. 5 GewO).", c: ["Polizei: hoheitlich, gesetzliche Eingriffsbefugnisse", "Sicherheitsdienst: privater Auftrag, keine Hoheitsrechte", "Jedermannsrechte und übertragene Rechte", "Erforderlichkeit"] },

  { u: "jedermann", d: 1, q: "Welche Rechte dürfen Wachpersonen nach § 34a Abs. 5 GewO gegenüber Dritten ausüben?", o: ["Die Jedermannsrechte, vom Auftraggeber vertraglich übertragene Selbsthilferechte und gegebenenfalls gesetzlich übertragene Befugnisse", ["Alle Befugnisse der Polizei, soweit sie im Dienst sind", "Polizeiliche Befugnisse stehen ihnen nicht zu."], ["Nur das Recht, die Polizei zu rufen", "Sie haben darüber hinaus Jedermannsrechte und übertragene Rechte."], ["Befugnisse nach der Hausordnung des eigenen Arbeitgebers", "Maßgeblich sind die Rechte des Auftraggebers am bewachten Objekt, nicht interne Regeln."]], e: "§ 34a Abs. 5 GewO stellt klar: Wachpersonen haben keine Sonderrechte. Sie handeln wie jedermann und mit den Rechten des Auftraggebers.", r: "§ 34a Abs. 5 GewO" },
  { u: "jedermann", t: "mc", d: 1, q: "Welche zwei Rechte gehören zu den Jedermannsrechten?", o: ["Notwehr und Nothilfe", "Vorläufige Festnahme nach § 127 Abs. 1 StPO", ["Identitätsfeststellung nach § 163b StPO", "Diese Befugnis haben nur Staatsanwaltschaft und Polizei."], ["Beschlagnahme von Beweismitteln", "Das ist eine hoheitliche Maßnahme."]], e: "Jedermannsrechte sind Notwehr/Nothilfe, Notstand, Selbsthilfe und die vorläufige Festnahme nach § 127 Abs. 1 StPO.", r: "§ 32 StGB; § 127 Abs. 1 StPO" },
  { u: "jedermann", d: 2, q: "Welchen Grundsatz müssen Wachpersonen nach § 34a Abs. 5 GewO bei der Ausübung ihrer Rechte beachten?", o: ["Den Grundsatz der Erforderlichkeit", ["Den Grundsatz der Gewinnmaximierung", "Wirtschaftliche Ziele rechtfertigen keine Eingriffe."], ["Den Grundsatz der Abschreckung", "Abschreckung ist kein Maßstab für die Rechtsausübung."], ["Den Grundsatz der Öffentlichkeit", "Dieser Grundsatz gilt für Gerichtsverhandlungen."]], e: "Erforderlich ist das mildeste Mittel, das den Zweck sicher erreicht. Mehr darf nicht eingesetzt werden.", r: "§ 34a Abs. 5 Satz 2 GewO" },
  { u: "jedermann", t: "tf", d: 1, a: false, q: "Die Jedermannsrechte stehen Wachpersonen in größerem Umfang zu als anderen Privatpersonen.", e: "Der Umfang ist für alle gleich. Durch Ausbildung und Aufgabe wird von Wachpersonen eher ein besonders besonnenes Vorgehen erwartet.", r: "§ 34a Abs. 5 GewO" },
  { u: "jedermann", t: "zu", d: 2, q: "Ordne jedem Recht die passende Rechtsgrundlage zu.", p: [["Notwehr", "§ 32 StGB"], ["Rechtfertigender Notstand", "§ 34 StGB"], ["Selbsthilfe", "§ 229 BGB"], ["Vorläufige Festnahme", "§ 127 StPO"]], e: "Diese vier Normen bilden den Kern der Jedermannsrechte." },
  { u: "jedermann", d: 2, q: "Was sind „vertraglich übertragene Selbsthilferechte“ im Sinne des § 34a Abs. 5 GewO?", o: ["Rechte des Auftraggebers wie das Hausrecht und die Besitzschutzrechte, die die Wachperson für ihn ausübt", ["Sonderrechte, die die IHK mit der Sachkundeprüfung verleiht", "Die IHK verleiht keine Eingriffsrechte."], ["Befugnisse, die die Polizei im Einzelfall überträgt", "Die Polizei überträgt keine Befugnisse durch Absprache."], ["Rechte aus dem Arbeitsvertrag gegenüber dem Arbeitgeber", "Gemeint sind Rechte gegenüber Dritten, nicht arbeitsrechtliche Ansprüche."]], e: "Der Auftraggeber kann nur Rechte übertragen, die er selbst hat – vor allem Hausrecht und Besitzschutz.", r: "§ 34a Abs. 5 GewO; §§ 855, 859, 860 BGB" },
  { u: "jedermann", d: 2, f: 1, q: "Auf dem Gehweg vor dem bewachten Objekt wird ein Passant von zwei Personen getreten. Was darf die Wachperson?", o: ["Sie darf Nothilfe leisten und verständigt die Polizei.", ["Nichts, weil der Gehweg nicht zum Objekt gehört", "Nothilfe ist ein Jedermannsrecht und nicht an das Objekt gebunden."], ["Sie darf den Tätern einen Platzverweis erteilen.", "Platzverweise erteilt nur die Polizei."], ["Sie darf nur zusehen und später als Zeuge aussagen.", "Wer nicht hilft, obwohl es zumutbar ist, kann sich nach § 323c StGB strafbar machen."]], e: "Nothilfe nach § 32 StGB darf jeder leisten. Eigensicherung beachten und sofort die Polizei rufen.", r: "§ 32 StGB; § 323c StGB" },
  { u: "jedermann", t: "tf", d: 1, a: true, q: "Wehrt eine Wachperson einen gegenwärtigen rechtswidrigen Angriff auf einen Kollegen ab, handelt sie in Nothilfe.", e: "Nothilfe ist Notwehr zugunsten eines anderen (§ 32 Abs. 2 StGB: „von sich oder einem anderen“).", r: "§ 32 StGB" },
  { u: "jedermann", t: "fa", d: 2, q: "Nenne die Rechte, auf die sich eine Wachperson nach § 34a Abs. 5 GewO stützen kann, und den dabei zu beachtenden Grundsatz.", m: "Erstens die Rechte, die jedermann im Fall einer Notwehr, eines Notstands oder einer Selbsthilfe zustehen, dazu die vorläufige Festnahme nach § 127 Abs. 1 StPO. Zweitens die vom Auftraggeber vertraglich übertragenen Selbsthilferechte, insbesondere Hausrecht und Besitzschutz. Drittens – nur falls vorhanden – gesetzlich übertragene Befugnisse. Bei allen ist der Grundsatz der Erforderlichkeit zu beachten.", c: ["Jedermannsrechte", "vertraglich übertragene Selbsthilferechte", "gesetzlich übertragene Befugnisse", "Erforderlichkeit"] },

  { u: "soo", d: 2, q: "Was umfasst der Begriff „öffentliche Sicherheit“?", o: ["Die Unverletzlichkeit der Rechtsordnung, der Rechte und Rechtsgüter des Einzelnen sowie der Einrichtungen und Veranstaltungen des Staates", ["Die ungeschriebenen Regeln des guten Benehmens", "Das beschreibt die öffentliche Ordnung."], ["Nur den Schutz staatlicher Gebäude", "Der Begriff ist deutlich weiter."], ["Die Sicherheit auf Privatgrundstücken", "Der Begriff knüpft nicht an Privatgrundstücke an."]], e: "Die öffentliche Sicherheit hat drei Schutzgüter: Rechtsordnung, Individualrechtsgüter und staatliche Einrichtungen. Das PolG NRW verwendet den Begriff, definiert ihn aber nicht; die Definition stammt aus Rechtsprechung und Lehre.", r: "§ 1 Abs. 1, § 8 Abs. 1 PolG NRW (Begriff); Definition nach Rechtsprechung und Lehre" },
  { u: "soo", d: 2, q: "Was versteht man unter „öffentlicher Ordnung“?", o: ["Ungeschriebene Regeln, deren Befolgung als unerlässliche Voraussetzung eines geordneten Zusammenlebens gilt", ["Alle geschriebenen Gesetze", "Die geschriebene Rechtsordnung gehört zur öffentlichen Sicherheit."], ["Die Hausordnung eines Gebäudes", "Eine Hausordnung ist eine private Regelung."], ["Die Dienstanweisung des Sicherheitsunternehmens", "Das ist eine betriebliche Regelung."]], e: "Die öffentliche Ordnung erfasst ungeschriebene Wertvorstellungen der Allgemeinheit. Das Gesetz definiert den Begriff nicht; die Definition stammt aus Rechtsprechung und Lehre.", r: "§ 1 Abs. 1 PolG NRW; § 1 Abs. 1 OBG NRW (Begriff); Definition nach Rechtsprechung und Lehre" },
  { u: "soo", d: 2, q: "Was ist eine Gefahr im Sinne des Polizei- und Ordnungsrechts?", o: ["Eine Sachlage, die bei ungehindertem Ablauf mit hinreichender Wahrscheinlichkeit zu einem Schaden führt", ["Jede denkbare Möglichkeit eines Schadens", "Die bloße Möglichkeit genügt nicht."], ["Ein bereits eingetretener Schaden", "Ein eingetretener Schaden ist eine Störung."], ["Ein Verhalten, das jemand als unangenehm empfindet", "Bloße Belästigungen sind noch keine Gefahr."]], e: "Gefahr heißt: hinreichende Wahrscheinlichkeit eines Schadens in absehbarer Zeit. § 8 Abs. 1 PolG NRW spricht von einer „im einzelnen Falle bestehenden, konkreten Gefahr“; die nähere Definition stammt aus Rechtsprechung und Lehre.", r: "§ 8 Abs. 1 PolG NRW; § 14 Abs. 1 OBG NRW; Definition nach Rechtsprechung und Lehre" },
  { u: "soo", t: "mc", d: 2, q: "Welche zwei Elemente gehören zum Grundsatz der Verhältnismäßigkeit?", o: ["Erforderlichkeit – es gibt kein milderes, gleich wirksames Mittel", "Angemessenheit – der Nachteil steht nicht außer Verhältnis zum Zweck", ["Schnelligkeit – die schnellste Maßnahme ist zu wählen", "Schnelligkeit ist kein Element der Verhältnismäßigkeit."], ["Abschreckung – die Maßnahme muss andere abschrecken", "Abschreckung ist kein Element der Verhältnismäßigkeit."]], e: "Verhältnismäßig ist eine Maßnahme, die geeignet, erforderlich und angemessen ist. Für die Polizei in NRW steht der Grundsatz in § 2 PolG NRW: das am wenigsten beeinträchtigende Mittel; kein Nachteil, der erkennbar außer Verhältnis zum Erfolg steht.", r: "§ 2 PolG NRW; § 15 OBG NRW; Art. 20 Abs. 3 GG" },
  { u: "soo", t: "tf", d: 1, a: true, q: "Eine Ordnungswidrigkeit wird mit einer Geldbuße geahndet, nicht mit einer Strafe.", e: "Ordnungswidrigkeiten sind Verwaltungsunrecht (§ 1 OWiG). Geld- und Freiheitsstrafen gibt es nur bei Straftaten.", r: "§ 1 OWiG" },
  { u: "soo", d: 1, q: "Wer ist für die Abwehr von Gefahren für die öffentliche Sicherheit und Ordnung zuständig?", o: ["Polizei und Ordnungsbehörden", ["Private Sicherheitsdienste", "Sie schützen private Rechtsgüter ihrer Auftraggeber."], ["Die Industrie- und Handelskammer", "Die IHK hat keine Gefahrenabwehraufgaben."], ["Die Berufsgenossenschaft", "Sie ist Träger der gesetzlichen Unfallversicherung."]], e: "Gefahrenabwehr ist eine hoheitliche Aufgabe. In NRW weisen § 1 Abs. 1 PolG NRW und § 1 Abs. 1 OBG sie der Polizei und den Ordnungsbehörden zu.", r: "§ 1 Abs. 1 PolG NRW; § 1 Abs. 1 OBG NRW" },

  { u: "hausrecht", d: 1, q: "Wer ist Inhaber des Hausrechts an einem vermieteten Ladenlokal?", o: ["Der Mieter als berechtigter Besitzer", ["Immer nur der Eigentümer des Gebäudes", "Mit der Vermietung geht das Hausrecht an den Räumen auf den Mieter über."], ["Die Wachperson, sobald sie den Dienst antritt", "Sie übt das Hausrecht nur aus, wenn es ihr übertragen wurde."], ["Die Polizei", "Die Polizei hat kein privates Hausrecht an fremden Räumen."]], e: "Das Hausrecht steht dem zu, der die tatsächliche Verfügungsgewalt berechtigt ausübt – bei Vermietung dem Mieter.", r: "§§ 854, 858 ff., 903 BGB" },
  { u: "hausrecht", d: 1, q: "Wie erhält eine Wachperson das Recht, im Objekt ein Hausverbot auszusprechen?", o: ["Durch Übertragung des Hausrechts vom Berechtigten, z. B. im Bewachungsvertrag und in der Dienstanweisung", ["Automatisch durch die Unterrichtung bei der IHK", "Die Unterrichtung verleiht keine Rechte am Objekt."], ["Durch das Tragen von Dienstkleidung", "Kleidung verleiht keine Rechte."], ["Durch eine Genehmigung der Polizei", "Die Polizei verfügt nicht über das private Hausrecht."]], e: "Das Hausrecht ist ein privates Recht, das der Inhaber ganz oder teilweise übertragen kann.", r: "§ 34a Abs. 5 GewO; § 855 BGB" },
  { u: "hausrecht", d: 2, f: 1, q: "Ein Besucher beleidigt im Foyer wiederholt andere Gäste. Die Wachperson spricht im Auftrag des Betreibers ein Hausverbot aus. Der Besucher bleibt. Welche Aussage trifft zu?", o: ["Er begeht Hausfriedensbruch; die Wachperson darf ihn mit angemessenen Mitteln hinausbegleiten und die Polizei rufen.", ["Die Wachperson muss ihn gewähren lassen, bis ein Gericht entschieden hat.", "Besitzwehr und Notwehr erlauben die Durchsetzung des Hausrechts mit erforderlichen Mitteln."], ["Die Wachperson darf ihn zur Strafe in einen Raum einsperren.", "Das wäre Freiheitsberaubung; Strafen verhängt nur der Staat."], ["Das Hausverbot ist unwirksam, weil es nur mündlich erfolgte.", "Ein Hausverbot kann mündlich ausgesprochen werden."]], e: "Wer ohne Befugnis verweilt und sich trotz Aufforderung des Berechtigten nicht entfernt, erfüllt § 123 StGB. Die Durchsetzung muss erforderlich und angemessen sein.", r: "§ 123 StGB; § 859 BGB; § 32 StGB" },
  { u: "hausrecht", t: "mc", d: 2, q: "Welche zwei Aussagen zum Hausverbot sind richtig?", o: ["Es kann mündlich oder schriftlich ausgesprochen werden.", "Es darf nicht an Merkmale wie ethnische Herkunft oder Religion anknüpfen.", ["Es gilt automatisch bundesweit für alle Filialen aller Unternehmen.", "Es gilt für den Bereich, für den der Berechtigte es ausspricht."], ["Es darf nur von der Polizei ausgesprochen werden.", "Es ist ein Recht des Hausrechtsinhabers."]], e: "Das Hausverbot ist formfrei. Benachteiligungen wegen der im AGG genannten Merkmale sind bei Geschäften mit allgemeinem Publikumsverkehr unzulässig.", r: "§§ 903, 1004 BGB; § 19 AGG" },
  { u: "hausrecht", t: "tf", d: 1, a: false, q: "Das Hausrecht erlaubt es, Taschen von Besuchern auch gegen deren Willen zu durchsuchen.", e: "Das Hausrecht erlaubt, Bedingungen für den Zutritt zu stellen und den Zutritt zu verweigern. Eine Durchsuchung gegen den Willen deckt es nicht.", r: "§§ 903, 1004 BGB" },
  { u: "hausrecht", d: 2, f: 1, q: "An der Einlasskontrolle einer Diskothek verweigert ein Gast die in der Hausordnung vorgesehene Taschenkontrolle. Wie handelt die Wachperson richtig?", o: ["Sie verweigert ihm höflich den Einlass.", ["Sie durchsucht die Tasche gegen seinen Willen.", "Das wäre ein unzulässiger Zwang."], ["Sie hält ihn fest und ruft die Polizei.", "Die Weigerung ist keine Straftat; ein Festnahmegrund fehlt."], ["Sie nimmt ihm die Tasche ab und verwahrt sie.", "Die Wegnahme wäre verbotene Eigenmacht."]], e: "Die Kontrolle ist Zutrittsbedingung. Wer sie ablehnt, erhält keinen Einlass – mehr nicht.", r: "§ 903 BGB; Hausordnung" },
  { u: "hausrecht", d: 2, q: "Gilt das übertragene Hausrecht auch auf dem öffentlichen Gehweg vor dem bewachten Gebäude?", o: ["Nein, es endet an der Grenze des befriedeten Besitztums.", ["Ja, im Umkreis von 50 Metern", "Eine solche Regel gibt es nicht."], ["Ja, wenn die Störung vom Objekt ausging", "Auch dann besteht auf öffentlichem Grund kein Hausrecht."], ["Ja, wenn die Wachperson Dienstkleidung trägt", "Dienstkleidung erweitert das Hausrecht nicht."]], e: "Auf öffentlichem Verkehrsgrund hat der Auftraggeber kein Hausrecht. Dort bleiben nur die Jedermannsrechte.", r: "§ 903 BGB; § 123 StGB" },
  { u: "hausrecht", t: "fa", d: 2, f: 1, q: "In einem Einkaufszentrum pöbelt ein erkennbar alkoholisierter Mann Kunden an. Beschreibe dein Vorgehen als Wachperson mit übertragenem Hausrecht.", m: "Lage einschätzen und Eigensicherung beachten: Abstand halten, Kollegen informieren. Den Mann ruhig und respektvoll ansprechen und auffordern, das Verhalten einzustellen. Bleibt das ohne Erfolg, auf die Hausordnung hinweisen und im Namen des Betreibers ein Hausverbot aussprechen; zum Verlassen auffordern und zum Ausgang begleiten. Weigert er sich, liegt Hausfriedensbruch vor; die Polizei verständigen. Zwang nur soweit erforderlich und angemessen. Vorgang mit Zeit, Ort, Beteiligten und Zeugen dokumentieren.", c: ["Eigensicherung, Unterstützung", "ruhige Ansprache, Deeskalation", "Hausverbot aufgrund übertragenen Hausrechts", "§ 123 StGB, Polizei", "Verhältnismäßigkeit", "Dokumentation"] },

  { u: "koop", d: 1, q: "Welche Notrufnummer gilt in Deutschland für Feuerwehr und Rettungsdienst?", o: ["112", ["110", "110 ist der Notruf der Polizei."], ["115", "115 ist die Behördennummer."], ["116 117", "116 117 ist der ärztliche Bereitschaftsdienst."]], e: "112 ist der europaweite Notruf für Feuerwehr und Rettungsdienst, 110 der Polizeinotruf.", r: "Lernhinweis – bundesweit einheitliche Notrufnummern 110 und 112" },
  { u: "koop", d: 2, f: 1, q: "Nach einem Einbruch im bewachten Objekt trifft die Polizei ein. Wie verhält sich die Wachperson richtig?", o: ["Sie schildert die Lage, übergibt ihre Feststellungen und folgt den Weisungen der Polizei.", ["Sie setzt ihre eigenen Ermittlungen fort und befragt Verdächtige.", "Ermittlungen sind Aufgabe der Polizei."], ["Sie verweigert der Polizei den Zutritt, bis der Auftraggeber zustimmt.", "Das behindert die Strafverfolgung."], ["Sie räumt den Tatort auf, damit der Betrieb weiterlaufen kann.", "Spuren würden vernichtet."]], e: "Mit dem Eintreffen der Polizei geht die Einsatzleitung auf sie über. Die Wachperson unterstützt als Zeugin und Objektkundige.", r: "§ 163 StPO" },
  { u: "koop", t: "mc", d: 2, q: "Welche zwei Maßnahmen gehören zur Tatortsicherung bis zum Eintreffen der Polizei?", o: ["Tatort absperren und nichts verändern", "Zeugen bitten zu bleiben und Beobachtungen notieren", ["Fingerabdrücke mit Klebeband sichern", "Spurensicherung ist Aufgabe der Polizei."], ["Verdächtige Gegenstände einsammeln und sortieren", "Dadurch werden Spuren verändert."]], e: "Die Wachperson schützt Spuren vor Veränderung und hält Informationen fest.", r: "Rahmenplan 1a (Zusammenarbeit)" },
  { u: "koop", t: "tf", d: 1, a: true, q: "Rechtmäßige Weisungen der Polizei am Einsatzort hat auch die Wachperson zu befolgen.", e: "Die Polizei handelt hoheitlich. Sie kann nach § 8 Abs. 1 PolG NRW die notwendigen Maßnahmen zur Gefahrenabwehr treffen; ihre rechtmäßigen Anordnungen gelten gegenüber jedermann.", r: "§ 8 Abs. 1, § 34 PolG NRW" },
  { u: "koop", t: "fa", d: 1, q: "Welche Angaben gehören in einen Notruf?", m: "Wo ist es passiert (Ort, Adresse, Zufahrt)? Was ist passiert? Wie viele Verletzte oder Betroffene gibt es? Welche Verletzungen oder Gefahren liegen vor? Wer meldet? Danach auf Rückfragen warten – die Leitstelle beendet das Gespräch.", c: ["Wo", "Was", "Wie viele", "Welche Verletzungen/Gefahren", "Warten auf Rückfragen"] },
  { u: "koop", d: 2, q: "Was ändert eine Ordnungspartnerschaft zwischen Kommune, Polizei und Sicherheitsunternehmen an den Befugnissen der Wachpersonen?", o: ["Nichts – sie dient der Abstimmung und dem Informationsaustausch.", ["Die Wachpersonen erhalten Polizeibefugnisse für die Dauer der Partnerschaft.", "Befugnisse können nur durch Gesetz übertragen werden."], ["Die Wachpersonen dürfen Bußgelder erheben.", "Das ist eine hoheitliche Aufgabe."], ["Die Polizei gibt ihre Zuständigkeit ab.", "Die Zuständigkeit der Polizei bleibt bestehen."]], e: "Kooperationen verbessern die Zusammenarbeit, erweitern aber keine Befugnisse.", r: "§ 34a Abs. 5 GewO; Rahmenplan 1a" }
]);

SK.fragen("gew", [
  { u: "erlaubnis", d: 1, q: "Wer benötigt eine Erlaubnis nach § 34a Abs. 1 GewO?", o: ["Wer gewerbsmäßig Leben oder Eigentum fremder Personen bewachen will", ["Jede angestellte Wachperson", "Angestellte brauchen keine eigene Erlaubnis, sondern Zuverlässigkeit und Qualifikation."], ["Wer sein eigenes Grundstück bewacht", "Die Bewachung eigenen Eigentums ist kein Bewachungsgewerbe."], ["Jeder Hausmeister", "Hausmeistertätigkeit ist keine gewerbsmäßige Bewachung fremden Eigentums."]], e: "Das Bewachungsgewerbe ist erlaubnispflichtig. Die Erlaubnis muss vor Beginn der Tätigkeit vorliegen.", r: "§ 34a Abs. 1 GewO" },
  { u: "erlaubnis", t: "mc", d: 2, q: "In welchen zwei Fällen ist die Erlaubnis nach § 34a GewO zu versagen?", o: ["Der Antragsteller besitzt nicht die erforderliche Zuverlässigkeit.", "Der Antragsteller lebt in ungeordneten Vermögensverhältnissen.", ["Der Antragsteller ist jünger als 30 Jahre.", "Ein solches Mindestalter kennt das Gesetz nicht."], ["Der Antragsteller hat keinen Führerschein.", "Ein Führerschein ist keine Erlaubnisvoraussetzung."]], e: "Versagungsgründe sind fehlende Zuverlässigkeit, ungeordnete Vermögensverhältnisse, fehlende Sachkundeprüfung und fehlender Nachweis der Haftpflichtversicherung.", r: "§ 34a Abs. 1 Satz 3 GewO" },
  { u: "erlaubnis", d: 2, q: "Welchen Qualifikationsnachweis muss der Gewerbetreibende selbst für die Erlaubnis erbringen?", o: ["Die bestandene Sachkundeprüfung vor der IHK", ["Nur die Teilnahme an der Unterrichtung", "Für Gewerbetreibende genügt die Unterrichtung nicht."], ["Eine abgeschlossene Polizeiausbildung", "Sie ist nicht vorgeschrieben."], ["Keinen – es genügt die Gewerbeanzeige", "Das Gewerbe ist erlaubnispflichtig; die Anzeige allein genügt nicht."]], e: "Der Gewerbetreibende und die mit der Leitung beauftragten Personen müssen die Sachkundeprüfung nachweisen.", r: "§ 34a Abs. 1 Satz 3 Nr. 3 GewO" },
  { u: "erlaubnis", d: 2, q: "Welche Verurteilung spricht nach § 34a GewO in der Regel gegen die Zuverlässigkeit?", o: ["Eine rechtskräftige Verurteilung zu einer Freiheitsstrafe wegen bestimmter Straftaten in den letzten fünf Jahren", ["Jedes Verwarnungsgeld im Straßenverkehr", "Verwarnungsgelder begründen keine Regelunzuverlässigkeit."], ["Eine Verurteilung vor mehr als 30 Jahren", "Das Gesetz stellt auf die letzten fünf Jahre ab."], ["Ein verlorener Zivilprozess", "Zivilprozesse sind kein Regelbeispiel."]], e: "§ 34a GewO nennt Regelbeispiele der Unzuverlässigkeit, u. a. Verurteilungen zu Freiheitsstrafe, Jugendstrafe oder Geldstrafe von mindestens 90 Tagessätzen wegen bestimmter Delikte in den letzten fünf Jahren.", r: "§ 34a Abs. 1 Satz 4 GewO" },
  { u: "erlaubnis", t: "tf", d: 1, a: true, q: "Die Erlaubnis nach § 34a GewO kann mit Auflagen verbunden werden, soweit dies zum Schutz der Allgemeinheit oder der Auftraggeber erforderlich ist.", e: "Das sieht § 34a Abs. 1 GewO ausdrücklich vor; Auflagen können auch nachträglich angeordnet werden.", r: "§ 34a Abs. 1 Satz 2 GewO" },
  { u: "erlaubnis", d: 2, q: "Welche Behörde entscheidet über die Erlaubnis nach § 34a GewO?", o: ["Die nach Landesrecht zuständige Behörde, in der Regel das Gewerbe- oder Ordnungsamt", ["Die Industrie- und Handelskammer", "Die IHK nimmt die Sachkundeprüfung ab und führt die Unterrichtung durch."], ["Die Polizei", "Die Polizei wird beteiligt, entscheidet aber nicht."], ["Die Berufsgenossenschaft", "Sie ist für die Unfallversicherung zuständig."]], e: "Erlaubnisbehörde ist die nach Landesrecht zuständige Behörde. Sie holt u. a. Auskünfte zur Zuverlässigkeit ein.", r: "§ 34a Abs. 1 GewO; Zuständigkeit nach Landesrecht (für NRW hier nicht im Wortlaut geprüft)" },
  { u: "erlaubnis", t: "fa", d: 2, q: "Nenne die vier Gründe, aus denen die Erlaubnis nach § 34a Abs. 1 GewO zu versagen ist.", m: "Die Erlaubnis ist zu versagen, wenn 1. der Antragsteller oder eine mit der Leitung beauftragte Person nicht die erforderliche Zuverlässigkeit besitzt, 2. der Antragsteller in ungeordneten Vermögensverhältnissen lebt, 3. die Sachkundeprüfung vor der IHK nicht nachgewiesen wird oder 4. der Nachweis einer Haftpflichtversicherung fehlt.", c: ["Unzuverlässigkeit", "ungeordnete Vermögensverhältnisse", "fehlende Sachkundeprüfung", "fehlender Haftpflichtnachweis"] },

  { u: "taetig", d: 2, q: "Für welche Tätigkeit verlangt § 34a GewO die Sachkundeprüfung?", o: ["Schutz vor Ladendieben", ["Pfortendienst in einem nicht öffentlich zugänglichen Werk", "Hier genügt die Unterrichtung."], ["Nächtlicher Objektschutz in einem verschlossenen Lager", "Hier genügt die Unterrichtung."], ["Bestreifung eines umzäunten Baustellengeländes", "Hier genügt die Unterrichtung."]], e: "Der Schutz vor Ladendieben ist eine der im Gesetz aufgezählten sachkundepflichtigen Tätigkeiten.", r: "§ 34a Abs. 1a Satz 2 Nr. 2 GewO" },
  { u: "taetig", t: "mc", d: 2, q: "Welche zwei Tätigkeiten sind sachkundepflichtig?", o: ["Kontrollgänge im öffentlichen Verkehrsraum", "Bewachungen im Einlassbereich gastgewerblicher Diskotheken", ["Empfangsdienst in einem Bürogebäude ohne Publikumsverkehr", "Hier genügt die Unterrichtung."], ["Parkplatzeinweisung auf einem Firmengelände", "Hier genügt die Unterrichtung."]], e: "Sachkundepflichtig sind Kontrollgänge im öffentlichen Verkehrsraum oder in Hausrechtsbereichen mit tatsächlich öffentlichem Verkehr, Schutz vor Ladendieben, Einlass gastgewerblicher Diskotheken sowie leitende Funktionen in Flüchtlingsunterkünften und bei zugangsgeschützten Großveranstaltungen.", r: "§ 34a Abs. 1a Satz 2 GewO" },
  { u: "taetig", d: 3, f: 1, q: "Eine Wachperson soll in der Ladenpassage eines Bahnhofs Kontrollgänge durchführen. Die Passage ist Privatgelände, aber für jedermann zugänglich. Welche Qualifikation ist nötig?", o: ["Die Sachkundeprüfung, weil es sich um einen Hausrechtsbereich mit tatsächlich öffentlichem Verkehr handelt", ["Die Unterrichtung, weil es Privatgelände ist", "Entscheidend ist der tatsächlich öffentliche Verkehr."], ["Keine, weil der Eigentümer zustimmt", "Die Zustimmung ersetzt die gesetzliche Qualifikation nicht."], ["Ein Waffenschein", "Ein Waffenschein ist keine Qualifikation für Kontrollgänge."]], e: "Das Gesetz stellt Hausrechtsbereiche mit tatsächlich öffentlichem Verkehr dem öffentlichen Verkehrsraum gleich.", r: "§ 34a Abs. 1a Satz 2 Nr. 1 GewO" },
  { u: "taetig", d: 3, q: "Für wen ist bei der Bewachung einer Flüchtlingsunterkunft die Sachkundeprüfung vorgeschrieben?", o: ["Für Wachpersonen in leitender Funktion", ["Für alle dort eingesetzten Wachpersonen", "Das Gesetz verlangt sie hier nur für die leitende Funktion."], ["Für niemanden", "Für die leitende Funktion ist sie vorgeschrieben."], ["Nur für Dolmetscher", "Dolmetscher sind keine Wachpersonen im Sinne der Regel."]], e: "Bei Flüchtlingsunterkünften und zugangsgeschützten Großveranstaltungen knüpft die Sachkundepflicht an die leitende Funktion an.", r: "§ 34a Abs. 1a Satz 2 Nr. 4 und 5 GewO" },
  { u: "taetig", t: "tf", d: 2, a: false, q: "Bei einer zugangsgeschützten Großveranstaltung müssen alle eingesetzten Ordner die Sachkundeprüfung nachweisen.", e: "Die Sachkundeprüfung ist dort nur für Wachpersonen in leitender Funktion vorgeschrieben. Für die übrigen genügt die Unterrichtung.", r: "§ 34a Abs. 1a Satz 2 Nr. 5 GewO" },
  { u: "taetig", d: 2, q: "Welche Mindestvoraussetzungen muss jede Wachperson erfüllen?", o: ["Erforderliche Zuverlässigkeit und Nachweis der Unterrichtung durch die IHK", ["Sachkundeprüfung und Waffenschein", "Beides ist nur für bestimmte Tätigkeiten nötig."], ["Abitur und Führungszeugnis", "Ein Schulabschluss ist nicht vorgeschrieben."], ["Mitgliedschaft in einer Berufsgenossenschaft", "Mitglied der Berufsgenossenschaft ist das Unternehmen."]], e: "Mit Bewachungsaufgaben dürfen nur Personen beschäftigt werden, die zuverlässig sind und die Unterrichtung nachweisen; für bestimmte Tätigkeiten ist die Sachkundeprüfung nötig.", r: "§ 34a Abs. 1a Satz 1 GewO" },
  { u: "taetig", t: "fa", d: 2, q: "Zähle die Tätigkeiten auf, für die § 34a Abs. 1a GewO die Sachkundeprüfung verlangt.", m: "1. Kontrollgänge im öffentlichen Verkehrsraum oder in Hausrechtsbereichen mit tatsächlich öffentlichem Verkehr. 2. Schutz vor Ladendieben. 3. Bewachungen im Einlassbereich von gastgewerblichen Diskotheken. 4. Bewachungen von Aufnahmeeinrichtungen, Gemeinschaftsunterkünften und anderen Unterkünften für Asylsuchende oder Flüchtlinge in leitender Funktion. 5. Bewachungen von zugangsgeschützten Großveranstaltungen in leitender Funktion.", c: ["Kontrollgänge mit öffentlichem Verkehr", "Ladendiebstahl", "Diskotheken-Einlass", "Flüchtlingsunterkünfte – leitend", "Großveranstaltungen – leitend"] },

  { u: "gewo", d: 1, q: "Was besagt der Grundsatz der Gewerbefreiheit (§ 1 GewO)?", o: ["Der Betrieb eines Gewerbes ist jedermann gestattet, soweit das Gesetz keine Ausnahmen oder Beschränkungen vorsieht.", ["Gewerbe dürfen ohne jede Regel betrieben werden.", "Beschränkungen wie die Erlaubnispflicht sind zulässig."], ["Nur Deutsche dürfen ein Gewerbe betreiben.", "Die Gewerbefreiheit gilt für jedermann."], ["Gewerbe sind steuerfrei.", "Die Gewerbefreiheit sagt nichts über Steuern."]], e: "Die Gewerbefreiheit ist die Regel. § 34a GewO ist eine gesetzliche Beschränkung.", r: "§ 1 GewO" },
  { u: "gewo", t: "mc", d: 2, q: "Welche zwei Merkmale gehören zum Gewerbebegriff?", o: ["Selbstständige Tätigkeit", "Auf Dauer angelegt und auf Gewinnerzielung gerichtet", ["Weisungsgebundene Arbeit als Arbeitnehmer", "Arbeitnehmer sind nicht selbstständig."], ["Einmalige Gefälligkeit", "Es fehlt die Dauerhaftigkeit."]], e: "Gewerbe ist jede erlaubte, selbstständige, auf Dauer angelegte und auf Gewinn gerichtete Tätigkeit, ausgenommen Urproduktion und freie Berufe.", r: "§ 1 GewO; Rechtsprechung" },
  { u: "gewo", d: 2, q: "Was verlangt § 14 GewO beim Beginn eines Gewerbes?", o: ["Die Anzeige bei der zuständigen Behörde", ["Die Eintragung ins Bewacherregister durch die IHK", "Das Bewacherregister ist in § 11b GewO geregelt und ersetzt die Anzeige nicht."], ["Die Genehmigung der Polizei", "Die Polizei genehmigt keine Gewerbe."], ["Nichts – der Beginn ist formfrei", "Der Beginn ist anzeigepflichtig."]], e: "Beginn, Verlegung und Aufgabe eines Gewerbes sind anzuzeigen. Beim Bewachungsgewerbe kommt die Erlaubnis hinzu.", r: "§ 14 GewO" },
  { u: "gewo", d: 2, q: "Was erlaubt § 29 GewO der zuständigen Behörde?", o: ["Auskünfte zu verlangen und die Geschäftsräume zur Prüfung zu betreten (Auskunft und Nachschau)", ["Die Geschäftsräume ohne jede gesetzliche Voraussetzung zu durchsuchen und Unterlagen zu beschlagnahmen", "§ 29 GewO regelt Auskunft und Nachschau, keine strafprozessuale Durchsuchung."], ["Wachpersonen vorläufig festzunehmen", "Das regelt § 29 GewO nicht."], ["Preise für Bewachungsleistungen festzusetzen", "Preise sind nicht Gegenstand der Gewerbeaufsicht."]], e: "Der Gewerbetreibende muss Auskunft erteilen und die Nachschau dulden.", r: "§ 29 GewO" },
  { u: "gewo", t: "tf", d: 2, a: true, q: "Wer ohne die erforderliche Erlaubnis ein Bewachungsgewerbe betreibt, handelt ordnungswidrig.", e: "Das ergibt sich aus § 144 Abs. 1 Nr. 1 Buchst. f GewO. Es droht eine Geldbuße.", r: "§ 144 Abs. 1 Nr. 1 Buchst. f GewO" },
  { u: "gewo", d: 2, q: "Was kann die Behörde tun, wenn eine beschäftigte Wachperson unzuverlässig ist?", o: ["Dem Gewerbetreibenden die Beschäftigung dieser Person untersagen", ["Die Wachperson zu einer Freiheitsstrafe verurteilen", "Strafen verhängen nur Gerichte."], ["Nichts – das ist allein Sache des Arbeitgebers", "§ 34a GewO gibt der Behörde ein Untersagungsrecht."], ["Das Bewachungsobjekt schließen", "Dafür gibt die Vorschrift keine Grundlage."]], e: "Die Behörde kann die Beschäftigung einer Person mit Bewachungsaufgaben untersagen, wenn Tatsachen ihre Unzuverlässigkeit belegen.", r: "§ 34a Abs. 4 GewO" },

  { u: "pruef", d: 1, q: "Wer nimmt die Sachkundeprüfung ab?", o: ["Die Industrie- und Handelskammer", ["Das Ordnungsamt", "Das Ordnungsamt ist Erlaubnisbehörde."], ["Die Polizei", "Die Polizei prüft nicht."], ["Der Arbeitgeber", "Der Arbeitgeber kann die Prüfung nicht abnehmen."]], e: "Die Sachkundeprüfung kann bei jeder IHK abgelegt werden, die sie anbietet. Für die Abnahme errichtet die IHK mindestens einen Prüfungsausschuss.", r: "§ 10 BewachV" },
  { u: "pruef", d: 1, q: "Aus welchen Teilen besteht die Sachkundeprüfung?", o: ["Aus einem schriftlichen und einem mündlichen Teil", ["Nur aus einem schriftlichen Teil", "Es gibt zusätzlich einen mündlichen Teil."], ["Aus einem schriftlichen Teil und einer Schießprüfung", "Eine Schießprüfung gehört nicht dazu."], ["Aus einem mündlichen Teil und einem Sporttest", "Ein Sporttest gehört nicht dazu."]], e: "§ 11 BewachV: Die Prüfung ist in einen mündlichen und einen schriftlichen Teil zu gliedern.", r: "§ 11 BewachV" },
  { u: "pruef", d: 2, q: "Auf welche Sachgebiete legt § 11 BewachV den Schwerpunkt der mündlichen Prüfung?", o: ["Recht der öffentlichen Sicherheit und Ordnung einschließlich Gewerberecht sowie Umgang mit Menschen", ["Sicherheitstechnik und Unfallverhütung", "Diese Gebiete sind nicht als Schwerpunkt genannt."], ["Waffenrecht und Datenschutz", "Diese Gebiete sind nicht als Schwerpunkt genannt."], ["Ausschließlich Strafrecht", "Das Strafrecht ist nicht als Schwerpunkt genannt."]], e: "Schwerpunkt sind die Gebiete nach § 7 Nr. 1 und Nr. 6 BewachV.", r: "§ 11 Abs. 2 BewachV" },
  { u: "pruef", d: 2, q: "Wie viele Unterrichtsstunden umfasst die Unterrichtung nach der BewachV mindestens?", o: ["40", ["20", "Vorgeschrieben sind mindestens 40 Unterrichtsstunden."], ["80", "Vorgeschrieben sind mindestens 40 Unterrichtsstunden."], ["120", "Vorgeschrieben sind mindestens 40 Unterrichtsstunden."]], e: "§ 6 Abs. 1 BewachV: Die Unterrichtung hat mindestens 40 Unterrichtsstunden zu je 45 Minuten zu dauern. Sie erfolgt mündlich und endet ohne Prüfung.", r: "§ 6 Abs. 1 BewachV; Anlage 2 BewachV" },
  { u: "pruef", t: "tf", d: 1, a: false, q: "Die Unterrichtung bei der IHK endet mit einer schriftlichen Prüfung, die bestanden werden muss.", e: "Die Unterrichtung ist ein Verfahren ohne Prüfung. Die IHK stellt die Bescheinigung aus, wenn die Person ohne Fehlzeiten teilgenommen hat und die IHK sich durch geeignete Maßnahmen davon überzeugt hat, dass sie mit den Inhalten vertraut ist.", r: "§ 6 BewachV" },
  { u: "pruef", t: "mc", d: 2, q: "Welche zwei Aussagen zur mündlichen Sachkundeprüfung entsprechen der BewachV?", o: ["Es können bis zu fünf Prüflinge gleichzeitig geprüft werden.", "Sie soll je Prüfling etwa 15 Minuten dauern.", ["Sie ist öffentlich.", "Die Prüfung ist nicht öffentlich."], ["Sie kann den schriftlichen Teil ersetzen.", "Beide Teile müssen bestanden werden."]], e: "§ 11 BewachV: bis zu fünf Prüflinge gleichzeitig, etwa 15 Minuten je Prüfling, nicht öffentlich. Einzelne IHKs prüfen in kleineren Gruppen.", r: "§ 11 BewachV" },
  { u: "pruef", d: 2, q: "Wann ist die Sachkundeprüfung insgesamt bestanden?", o: ["Wenn sowohl der schriftliche als auch der mündliche Teil bestanden sind", ["Wenn der Durchschnitt beider Teile ausreichend ist", "Ein Ausgleich zwischen den Teilen findet nicht statt."], ["Wenn der schriftliche Teil bestanden ist", "Der mündliche Teil muss ebenfalls bestanden werden."], ["Wenn der Arbeitgeber die Eignung bestätigt", "Der Arbeitgeber entscheidet nicht über das Bestehen."]], e: "Beide Prüfungsteile müssen bestanden werden. Zur mündlichen Prüfung wird nur zugelassen, wer den schriftlichen Teil bestanden hat.", r: "§ 11 BewachV; Prüfungsordnungen der IHKs" },
  { u: "pruef", t: "zu", d: 2, q: "Ordne zu, welche Qualifikation mindestens erforderlich ist.", p: [["Gewerbetreibender im Bewachungsgewerbe", "Sachkundeprüfung"], ["Ladendetektiv", "Sachkundeprüfung (Tätigkeit nach Abs. 1a)"], ["Werkschutz im geschlossenen Werk", "Unterrichtung"]], e: "Für Gewerbetreibende und die im Gesetz aufgezählten Tätigkeiten ist die Sachkundeprüfung nötig, sonst genügt die Unterrichtung." },

  { u: "haft", d: 2, q: "Welche Mindestversicherungssumme schreibt die BewachV für Personenschäden vor?", o: ["1.000.000 Euro", ["250.000 Euro", "Das ist die Mindestsumme für Sachschäden."], ["15.000 Euro", "Das ist die Mindestsumme für das Abhandenkommen bewachter Sachen."], ["12.500 Euro", "Das ist die Mindestsumme für reine Vermögensschäden."]], e: "§ 14 BewachV: 1.000.000 € für Personenschäden, 250.000 € für Sachschäden, 15.000 € für das Abhandenkommen bewachter Sachen, 12.500 € für reine Vermögensschäden.", r: "§ 14 BewachV" },
  { u: "haft", t: "zu", d: 3, q: "Ordne jeder Schadensart die Mindestversicherungssumme nach der BewachV zu.", p: [["Personenschäden", "1.000.000 €"], ["Sachschäden", "250.000 €"], ["Abhandenkommen bewachter Sachen", "15.000 €"], ["Reine Vermögensschäden", "12.500 €"]], e: "Die Summen stehen in § 14 BewachV.", r: "§ 14 BewachV" },
  { u: "haft", d: 2, q: "Wozu dient die Haftpflichtversicherung des Bewachungsunternehmens?", o: ["Zur Deckung von Schäden, die den Auftraggebern oder Dritten bei der Durchführung des Bewachungsvertrags entstehen", ["Zur Absicherung der Wachpersonen bei Arbeitsunfällen", "Dafür ist die gesetzliche Unfallversicherung zuständig."], ["Zur Zahlung von Geldbußen des Unternehmens", "Geldbußen sind nicht versicherbar."], ["Zur Rechtsberatung der Kunden", "Das ist nicht Gegenstand der Haftpflichtversicherung."]], e: "Die Versicherung schützt Auftraggeber und Dritte. Ohne Nachweis gibt es keine Erlaubnis.", r: "§ 34a Abs. 1 GewO; § 14 BewachV" },
  { u: "haft", t: "tf", d: 2, a: true, q: "Die Haftpflichtversicherung muss für die gesamte Dauer der Gewerbeausübung aufrechterhalten werden.", e: "Der Nachweis der Haftpflichtversicherung ist Voraussetzung der Erlaubnis (§ 34a Abs. 1 Satz 3 Nr. 4 GewO). Das Versicherungsunternehmen muss der Behörde die Beendigung des Versicherungsvertrags unverzüglich anzeigen (§ 15 Abs. 2 BewachV).", r: "§ 34a Abs. 1 GewO; §§ 14, 15 BewachV" },

  { u: "dienst", d: 2, q: "Welchen Hinweis muss die Dienstanweisung nach § 17 BewachV enthalten?", o: ["Dass die Wachperson nicht die Eigenschaft und die Befugnisse eines Polizeivollzugsbeamten oder sonstigen Behördenbediensteten besitzt", ["Dass die Wachperson im Dienst polizeiliche Befugnisse hat", "Das Gegenteil ist richtig."], ["Dass die Wachperson keine Pausen machen darf", "Pausen regelt das Arbeitszeitrecht."], ["Dass die Wachperson jede Person durchsuchen darf", "Ein solches Recht besteht nicht."]], e: "Die Dienstanweisung stellt klar, dass Wachpersonen keine hoheitlichen Befugnisse haben.", r: "§ 17 Abs. 1 BewachV" },
  { u: "dienst", t: "mc", d: 2, q: "Welche zwei Aussagen zur Aushändigung der Dienstanweisung treffen nach § 17 BewachV zu?", o: ["Die Wachperson erhält einen Abdruck vor der ersten Aufnahme der Bewachungstätigkeit.", "Die Aushändigung erfolgt gegen Empfangsbescheinigung.", ["Es genügt, die Dienstanweisung im Büro auszuhängen.", "Vorgeschrieben ist die Aushändigung eines Abdrucks."], ["Die Dienstanweisung wird erst nach der Probezeit ausgehändigt.", "Sie ist vor der ersten Aufnahme der Tätigkeit auszuhändigen."]], e: "§ 17 Abs. 2 BewachV: Abdruck der Dienstanweisung vor der ersten Aufnahme der Bewachungstätigkeit gegen Empfangsbescheinigung.", r: "§ 17 Abs. 2 BewachV" },
  { u: "dienst", d: 1, q: "Wie lange gilt die Pflicht der Wachperson, Geschäfts- und Betriebsgeheimnisse Dritter zu wahren?", o: ["Auch nach dem Ausscheiden aus dem Unternehmen", ["Nur während der Arbeitszeit", "Die Pflicht gilt umfassend."], ["Bis zum Ende des jeweiligen Auftrags", "Sie gilt darüber hinaus."], ["Ein Jahr nach der Kündigung", "Eine solche Befristung nennt die BewachV nicht."]], e: "Der Gewerbetreibende hat seine Beschäftigten schriftlich zu verpflichten, Geschäfts- und Betriebsgeheimnisse Dritter auch nach ihrem Ausscheiden nicht unbefugt zu offenbaren.", r: "§ 17 Abs. 3 BewachV" },
  { u: "dienst", d: 2, f: 1, q: "Ein Bekannter fragt eine Wachperson, wann im bewachten Betrieb die Tageseinnahmen abgeholt werden. Wie reagiert sie richtig?", o: ["Sie gibt keine Auskunft und meldet die Anfrage ihrem Vorgesetzten.", ["Sie nennt die Uhrzeit, da es ein Bekannter ist.", "Das verletzt die Verschwiegenheitspflicht und gefährdet den Auftraggeber."], ["Sie nennt nur den Wochentag.", "Auch das ist eine unbefugte Offenbarung."], ["Sie verweist ihn an den Fahrer des Geldtransports.", "Damit würde sie die Ausforschung unterstützen."]], e: "Abläufe des Auftraggebers sind Betriebsgeheimnisse. Solche Anfragen können der Vorbereitung einer Straftat dienen.", r: "§ 17 Abs. 3 BewachV; GeschGehG" },
  { u: "dienst", t: "tf", d: 1, a: true, q: "Die Dienstanweisung regelt, wie der Wachdienst im Einzelnen durchzuführen ist.", e: "Der Gewerbetreibende hat den Wachdienst durch eine Dienstanweisung nach Maßgabe der BewachV zu regeln.", r: "§ 17 Abs. 1 BewachV" },
  { u: "dienst", t: "fa", d: 2, q: "Was regelt die Dienstanweisung nach § 17 BewachV und was ist bei ihrer Aushändigung zu beachten?", m: "Die Dienstanweisung regelt den Wachdienst. Sie muss den Hinweis enthalten, dass die Wachperson nicht die Eigenschaft und die Befugnisse eines Polizeivollzugsbeamten oder sonstigen Bediensteten einer Behörde besitzt. Sie muss außerdem bestimmen, dass Waffen im Dienst nur mit Zustimmung des Gewerbetreibenden geführt werden dürfen und jeder Gebrauch unverzüglich der Polizei und dem Gewerbetreibenden anzuzeigen ist. Die Wachperson erhält vor der ersten Aufnahme der Bewachungstätigkeit einen Abdruck der Dienstanweisung gegen Empfangsbescheinigung.", c: ["Regelung des Wachdienstes", "kein Polizeibeamter", "Waffen nur mit Zustimmung, Gebrauch anzeigen", "Aushändigung gegen Empfangsbescheinigung"] },

  { u: "ausweis", d: 1, q: "Was muss die Wachperson während des Wachdienstes mitführen?", o: ["Den vom Gewerbetreibenden ausgestellten Ausweis", ["Die Gewerbeerlaubnis des Unternehmens im Original", "Sie bleibt beim Gewerbetreibenden."], ["Ihr Prüfungszeugnis der IHK", "Es muss nicht mitgeführt werden."], ["Ein polizeiliches Führungszeugnis", "Es muss nicht mitgeführt werden."]], e: "Die Wachperson hat den Ausweis mitzuführen und auf Verlangen den Beauftragten der zuständigen Behörden vorzuzeigen.", r: "§ 18 BewachV" },
  { u: "ausweis", t: "mc", d: 2, q: "Welche zwei Angaben enthält der Ausweis nach § 18 BewachV?", o: ["Name und Vorname der Wachperson", "Name und Anschrift des Gewerbetreibenden", ["Die Privatanschrift der Wachperson", "Sie gehört nicht zu den Pflichtangaben."], ["Das Monatsgehalt", "Es gehört nicht auf den Ausweis."]], e: "Der Ausweis enthält u. a. den Namen der Wachperson, Angaben zum Gewerbetreibenden und zum Gewerbebetrieb, Unterschriften und die Bewacherregisteridentifikationsnummern.", r: "§ 18 BewachV" },
  { u: "ausweis", d: 2, q: "Welche Anforderung stellt die BewachV an die Gestaltung des Dienstausweises?", o: ["Er muss sich von amtlichen Ausweisen deutlich unterscheiden.", ["Er muss dem Polizeiausweis nachempfunden sein.", "Verwechslungen mit amtlichen Ausweisen sollen gerade vermieden werden."], ["Er muss ein Bundeswappen tragen.", "Hoheitszeichen sind nicht vorgesehen."], ["Er muss von der Polizei gesiegelt sein.", "Die Polizei siegelt den Ausweis nicht."]], e: "Der Ausweis ist kein amtliches Dokument und darf nicht so wirken.", r: "§ 18 BewachV" },
  { u: "ausweis", d: 3, q: "Für welche Wachpersonen schreibt die BewachV ein sichtbar getragenes Schild mit Namen oder Kennnummer und der Bezeichnung des Gewerbebetriebs vor?", o: ["Für Wachpersonen bei Kontrollgängen im öffentlichen Verkehrsraum, im Einlassbereich von Diskotheken sowie in Flüchtlingsunterkünften und bei zugangsgeschützten Großveranstaltungen", ["Für alle Wachpersonen ohne Ausnahme", "Die Pflicht ist auf bestimmte Tätigkeiten beschränkt."], ["Nur für Ladendetektive", "Für den Schutz vor Ladendieben gilt die Schildpflicht gerade nicht."], ["Nur für bewaffnete Wachpersonen", "Die Schildpflicht hängt nicht von der Bewaffnung ab."]], e: "Die Kennzeichnung gilt für Tätigkeiten nach § 34a Abs. 1a Satz 2 Nr. 1 und 3 bis 5 GewO. In Flüchtlingsunterkünften und bei Großveranstaltungen gilt sie auch für Wachpersonen in nicht leitender Funktion. Der Schutz vor Ladendieben (Nr. 2) ist ausgenommen.", r: "§ 18 Abs. 3 BewachV" },
  { u: "ausweis", d: 2, q: "Was verlangt die BewachV von der Dienstkleidung?", o: ["Sie darf nicht mit Uniformen der Streitkräfte oder behördlicher Vollzugsorgane verwechselt werden können.", ["Sie muss der Polizeiuniform des Landes entsprechen.", "Verwechslungsgefahr ist gerade verboten."], ["Sie muss bundesweit einheitlich blau sein.", "Eine einheitliche Farbe ist nicht vorgeschrieben."], ["Sie muss Rangabzeichen der Bundeswehr tragen.", "Amtsähnliche Abzeichen sind unzulässig."]], e: "Dienstkleidung und Abzeichen dürfen keine Verwechslung mit Uniformen und Amtsabzeichen ermöglichen.", r: "§ 19 Abs. 1 BewachV" },
  { u: "ausweis", t: "tf", d: 2, a: true, q: "Wachpersonen, die in Ausübung ihres Dienstes befriedetes Besitztum betreten sollen, müssen Dienstkleidung tragen.", e: "Das bestimmt § 19 Abs. 2 BewachV. So sind sie als berechtigte Personen erkennbar.", r: "§ 19 Abs. 2 BewachV" },
  { u: "ausweis", t: "tf", d: 1, a: false, q: "Der Dienstausweis einer Wachperson ist ein amtlicher Ausweis und berechtigt zu Personenkontrollen.", e: "Der Ausweis wird vom Gewerbetreibenden ausgestellt, ist kein amtliches Dokument und verleiht keine Befugnisse.", r: "§ 18 BewachV" },

  { u: "waffenbv", d: 2, q: "Unter welcher Voraussetzung darf eine Wachperson im Dienst eine Schusswaffe, eine Hieb- und Stoßwaffe oder ein Reizstoffsprühgerät führen?", o: ["Nur mit Zustimmung des Gewerbetreibenden – und nur, wenn die waffenrechtlichen Voraussetzungen erfüllt sind", ["Immer, wenn sie es für nötig hält", "Die eigene Einschätzung genügt nicht."], ["Wenn der Auftraggeber es mündlich wünscht", "Maßgeblich ist die Zustimmung des Gewerbetreibenden."], ["Wenn sie die Sachkundeprüfung nach § 34a GewO bestanden hat", "Diese Prüfung ersetzt weder Zustimmung noch waffenrechtliche Erlaubnis."]], e: "Die Dienstanweisung muss bestimmen, dass Waffen nur mit Zustimmung des Gewerbetreibenden geführt werden dürfen.", r: "§ 17 Abs. 1 BewachV; § 28 WaffG" },
  { u: "waffenbv", d: 2, f: 1, q: "Eine Wachperson setzt im Dienst ihr Reizstoffsprühgerät gegen einen Angreifer ein. Was hat sie anschließend zu tun?", o: ["Den Gebrauch unverzüglich der zuständigen Polizeidienststelle und dem Gewerbetreibenden anzeigen", ["Nichts, wenn niemand ernsthaft verletzt wurde", "Die Anzeigepflicht gilt für jeden Gebrauch."], ["Den Vorfall nur im privaten Notizbuch vermerken", "Das genügt nicht."], ["Den Gebrauch innerhalb eines Monats der IHK melden", "Die IHK ist dafür nicht zuständig."]], e: "Jeder Gebrauch der genannten Waffen ist unverzüglich anzuzeigen.", r: "§§ 17, 20 BewachV" },
  { u: "waffenbv", t: "mc", d: 2, q: "Welche zwei Pflichten hat der Gewerbetreibende nach § 20 BewachV im Umgang mit Waffen?", o: ["Er ist für die sichere Aufbewahrung der Waffen und der Munition verantwortlich.", "Er hat die ordnungsgemäße Rückgabe der Waffen und der Munition nach Beendigung des Wachdienstes sicherzustellen.", ["Er muss jeder Wachperson eine Schusswaffe aushändigen.", "Eine Bewaffnungspflicht gibt es nicht."], ["Er darf Waffen an Auftraggeber verleihen.", "Das wäre ein unzulässiges Überlassen."]], e: "§ 20 BewachV verpflichtet den Gewerbetreibenden zur sicheren Verwahrung und zur Kontrolle der Rückgabe.", r: "§ 20 BewachV" },
  { u: "waffenbv", t: "tf", d: 2, a: false, q: "Eine Wachperson darf ihre private, legal besessene Schreckschusswaffe ohne Weiteres im Dienst führen.", e: "Im Dienst dürfen Waffen nur mit Zustimmung des Gewerbetreibenden geführt werden. Die Unfallverhütungsvorschrift steht Schreckschusswaffen im Wachdienst zudem entgegen.", r: "§ 17 BewachV; DGUV Vorschrift 23" },

  { u: "buch", d: 2, q: "Was darf der Gewerbetreibende nach § 16 BewachV nur tun, wenn die Person zuverlässig, grundsätzlich volljährig und ausreichend befähigt ist?", o: ["Sie mit Bewachungsaufgaben beschäftigen", ["Sie in der Buchhaltung beschäftigen", "Die Vorschrift betrifft Bewachungsaufgaben."], ["Ihr ein Dienstfahrzeug überlassen", "Darum geht es in § 16 BewachV nicht."], ["Ihr Urlaub gewähren", "Urlaub regelt das Arbeitsrecht."]], e: "§ 16 BewachV knüpft die Beschäftigung mit Bewachungsaufgaben an Zuverlässigkeit, Volljährigkeit und Qualifikation.", r: "§ 16 BewachV" },
  { u: "buch", d: 2, q: "Worüber meldet der Gewerbetreibende Wachpersonen an, bevor er sie mit Bewachungsaufgaben beschäftigt?", o: ["Über das Bewacherregister", ["Über das Handelsregister", "Das Handelsregister erfasst Kaufleute und Gesellschaften."], ["Über das Bundeszentralregister", "Dort werden Verurteilungen eingetragen."], ["Über das Einwohnermeldeamt", "Dort wird der Wohnsitz gemeldet."]], e: "Wachpersonen und mit der Leitung beauftragte Personen werden über das Bewacherregister gemeldet; die Behörde prüft die Zuverlässigkeit.", r: "§ 11b GewO; § 16 BewachV" },
  { u: "buch", d: 2, q: "Welche Daten enthält das Bewacherregister nach § 11b GewO unter anderem?", o: ["Daten zu Gewerbetreibenden und Wachpersonen einschließlich Qualifikation und Zuverlässigkeitsprüfung", ["Die Dienstpläne aller Sicherheitsunternehmen", "Dienstpläne werden nicht erfasst."], ["Die Umsätze der Sicherheitsunternehmen", "Umsätze werden nicht erfasst."], ["Alle Strafanzeigen von Wachpersonen", "Strafanzeigen werden dort nicht gesammelt."]], e: "Das Register macht Qualifikation und Zuverlässigkeit bundesweit nachvollziehbar.", r: "§ 11b GewO" },
  { u: "buch", d: 3, q: "Wie lange sind die Aufzeichnungen nach § 21 BewachV aufzubewahren?", o: ["Bis zum Schluss des dritten auf den Zeitpunkt ihrer Entstehung folgenden Kalenderjahres", ["Sechs Monate", "Die Frist ist deutlich länger."], ["Zehn Jahre", "Diese Frist kennt das Handels- und Steuerrecht, nicht § 21 BewachV."], ["Dauerhaft", "Eine dauerhafte Aufbewahrung ist nicht vorgeschrieben."]], e: "§ 21 BewachV regelt Buchführung und Aufbewahrung; die Aufzeichnungen sind unverzüglich und in deutscher Sprache anzufertigen.", r: "§ 21 BewachV" },
  { u: "buch", t: "mc", d: 2, q: "Welche zwei Aussagen zur Buchführung nach § 21 BewachV treffen zu?", o: ["Die Aufzeichnungen sind unverzüglich anzufertigen.", "Die Aufzeichnungen sind in deutscher Sprache anzufertigen.", ["Die Aufzeichnungen dürfen erst am Jahresende erstellt werden.", "Sie sind unverzüglich anzufertigen."], ["Die Aufzeichnungen führt die Wachperson privat.", "Die Pflicht trifft den Gewerbetreibenden."]], e: "Aufgezeichnet werden u. a. Bewachungsverträge, Wachpersonen und Dienstanweisungen.", r: "§ 21 BewachV" },
  { u: "buch", t: "tf", d: 1, a: false, q: "Eine 17-jährige Person ohne anerkannten Berufsabschluss im Sicherheitsbereich darf mit Bewachungsaufgaben beschäftigt werden.", e: "Nach § 16 Abs. 1 BewachV muss die Person das 18. Lebensjahr vollendet haben oder einen in § 8 BewachV bezeichneten Abschluss besitzen.", r: "§ 16 Abs. 1 BewachV" },
  { u: "buch", t: "fa", d: 3, q: "Welche Pflichten hat der Gewerbetreibende gegenüber der Behörde und bei der Dokumentation? Nenne die wichtigsten.", m: "Er muss Wachpersonen und Leitungspersonal vor der Beschäftigung über das Bewacherregister melden und darf sie erst einsetzen, wenn Zuverlässigkeit und Qualifikation feststehen. Er muss die Haftpflichtversicherung nachweisen und aufrechterhalten. Er führt Aufzeichnungen nach § 21 BewachV, unverzüglich und in deutscher Sprache, und bewahrt sie bis zum Schluss des dritten Folgejahres auf. Der Behörde erteilt er Auskunft und duldet die Nachschau (§ 29 GewO). Jeden Waffengebrauch zeigt er an.", c: ["Meldung über Bewacherregister", "Haftpflichtnachweis", "Buchführung und Aufbewahrung", "Auskunft und Nachschau", "Anzeige Waffengebrauch"] }
]);
